  filter(bill_type == "Salary") |&gt;
  summarise(employees = n_distinct(payee_id), ddos = n_distinct(ddo_code),
            amount = sum(amount, na.rm = TRUE), .by = payee_account) |&gt;
  filter(employees &gt; 1) |&gt;
  arrange(desc(employees)) |&gt;
  collect()
